import{z as i,x as l,o as e,c as d,q as B,j as n,D as E,d as t,s as A,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"结构转型","description":"","frontmatter":{"title":"结构转型","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gd-structural-transformation.md","filePath":"econ/gd-structural-transformation.md","lastUpdated":1791063341000}'),m={name:"econ/gd-structural-transformation.md"};function u(p,a,c,h,f,D){const r=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=B('<h1 id="结构转型" tabindex="-1">结构转型 <a class="header-anchor" href="#结构转型" aria-label="Permalink to &quot;结构转型&quot;">​</a></h1><div class="epigraph"><p>增长不只是每个部门一起变大，而是农民变成工人、工人变成职员；总量路径是份额迁移的影子。</p><footer>—— 据 Kuznets；Kongsamut, Rebelo and Xie, &quot;Beyond Balanced Growth&quot;, REStud 2001 整理</footer></div><p><a href="/econ/gd-ideas-rivalry">上一课</a>把规模效应证伪，把长期增长改写成由人口增长驱动的半内生增长——但那仍是一个单部门世界：技术只有一条 \\(A\\)，经济只生产一种产品。增长的事实却带着结构：就业与产出份额沿发展路径大幅迁移，农业让位给制造业，制造业再让位给服务业。本课把部门维度接进增长模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>库兹涅茨事实：人均收入上升时，农业就业份额持续下降，服务业份额持续上升，制造业份额先升后降。单部门模型把这一切平均掉：它说不出谁在离开农业，也把服务业份额的上升当成噪声。缺口有两层：份额为什么会迁移（引擎是什么）；迁移如何污染加总——发展核算把低收入国的落后拆成资本、人力与残差，<a href="/econ/convergence-accounting">发展核算</a>的残差里有多少其实是「人还挤在低生产率部门」的结构账。<span class="marginnote">恩格尔定律用你家账本就能验证：收入翻倍后，吃饭的开销到不了两倍（食品的收入弹性小于一），而下馆子、旅游、看病涨得更快（弹性大于一）。放大到国家：越富，农业份额越低、服务业份额越高——偏好形状直接写进份额迁移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两个引擎。收入效应：偏好非位似，食品的收入弹性小于一、服务的弹性大于一，恩格尔定律随收入上升把份额从农业推向服务业。价格效应：部门间生产率增速不同，Baumol 1967 的成本病——停滞部门的相对价格持续上涨，名义份额被价格推着走。<span class="marginnote">「成本病」翻译成大白话：技术再进步，理发师一小时也只能剪那么多个头——理发业生产率几乎不涨，可理发师的工资得跟上制造业水涨船高，于是理发越来越贵。服务「变贵」不等于服务「变重要」，这是读名义份额时最容易踩的坑。</span>多部门建模把两个引擎装进增长框架：Kongsamut、Rebelo 与 Xie 2001 用带最低消费的 Stone-Geary 偏好，在服务业份额上升、农业份额下降的同时保住总量的卡尔多事实，称为广义平衡增长路径；Ngai 与 Pissarides 2007 证明，当部门产品以单位替代弹性加总时，生产率差异主要走相对价格而不拖累总量——制造业份额下降不是因为变得不重要，恰恰因为它生产率涨得最快、价格跌得最狠。低收入端另有一条农业约束：Gollin、Parente 与 Rogerson 2002 指出，农业生产率低时，喂饱全国必须困住大部分劳动力，食品约束解除是起飞的前提，这是<a href="/econ/malthus-to-modern">从马尔萨斯到现代增长</a>在部门口径上的续篇；剩余劳动的转移由 Lewis 1954 的双经济给出最早的表达。</p>',7)),(e(),n(s,null,{default:E(()=>[A(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E9%9D%9E%E4%BD%8D%E4%BC%BC%E5%81%8F%E5%A5%BD%EF%BC%9A%E6%81%A9%E6%A0%BC%E5%B0%94%E5%AE%9A%E5%BE%8B%22%5D%20--%3E%20SHIFT%5B%22%E4%BB%BD%E9%A2%9D%E8%BF%81%E7%A7%BB%22%5D%0A%20%20PROD%5B%22%E9%83%A8%E9%97%A8%E7%94%9F%E4%BA%A7%E7%8E%87%E5%A2%9E%E9%80%9F%E4%B8%8D%E5%90%8C%EF%BC%9A%E6%88%90%E6%9C%AC%E7%97%85%22%5D%20--%3E%20PRICE%5B%22%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E5%8F%98%E5%8A%A8%22%5D%0A%20%20PRICE%20--%3E%20SHIFT%0A%20%20SHIFT%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%E7%94%9F%E4%BA%A7%E7%8E%87%E4%B8%8E%E7%BB%93%E6%9E%84%E7%BA%A2%E5%88%A9%22%5D%0A%20%20AGG%20--%3E%20ACCT%5B%22%E5%8F%91%E5%B1%95%E6%A0%B8%E7%AE%97%E6%AE%8B%E5%B7%AE%E7%9A%84%E7%BB%93%E6%9E%84%E6%88%90%E5%88%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"结构红利是本课对核算的修正：当劳动从低边际产出的农业流向高生产率部门，加总生产率的上涨快于任何单一部门的自身进步——同一个人换个部门，产出就变了，没有新技术发生。",-1)),(e(),n(s,null,{default:E(()=>[A(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20FARM%5B%22%E5%86%9C%E6%88%B7%3A%20%E8%BE%B9%E9%99%85%E4%BA%A7%E5%87%BA%201000%20%E5%85%83%2F%E5%B9%B4%22%5D%20--%3E%20MOVE%5B%22%E8%BF%81%E7%A7%BB%E5%88%B0%E5%88%B6%E9%80%A0%E4%B8%9A%22%5D%0A%20%20MOVE%20--%3E%20FAC%5B%22%E5%90%8C%E4%B8%80%E4%BA%BA%3A%20%E4%BA%A7%E5%87%BA%208000%20%E5%85%83%2F%E5%B9%B4%22%5D%0A%20%20FAC%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%E7%94%9F%E4%BA%A7%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20AGG%20--%3E%20Q%7B%22%E6%9C%89%E6%96%B0%E6%8A%80%E6%9C%AF%E5%87%BA%E7%8E%B0%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20BONUS%5B%22%E7%BB%93%E6%9E%84%E7%BA%A2%E5%88%A9%3A%20%E4%B8%8D%E8%AE%B0%E6%8A%80%E6%9C%AF%20%E4%B9%9F%E4%B8%8D%E8%AE%B0%E9%94%99%E9%85%8D%22%5D%0A%20%20RES%5B%22%E5%8F%91%E5%B1%95%E6%A0%B8%E7%AE%97%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20BONUS%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">结构红利用数字看：一个人从边际产出 1000 元/年的农场搬进 8000 元/年的工厂，经济总量多了 7000 元，但没有发生任何技术进步。若农业还挤着四成就业，光把人挪出来就是一大块增长——发展核算把这笔账全记成「技术进步」就记错了。</span>低收入国发展核算残差里相当一块是这笔结构账：把它全读成「本国技术落后」会高估技术差距，把它全读成<a href="/econ/misallocation-tfp">错配</a>的楔子也会错——份额迁移可以是发展路径的自然形状，不必对应任何扭曲。价格口径同样重要：服务业名义份额上升有相当部分是成本病推高的相对价格，实际份额涨得慢得多；用名义值读结构，会高估去工业化与「服务业化」的程度。</p><p><span class="marginnote">Ngai–Pissarides 的条件是替代弹性接近一：若产品间替代弹性高，生产率停滞部门会被替代萎缩而非靠涨价守住名义份额，加总结果随之不同——参数决定引擎权重。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两个引擎的相对权重对偏好与替代弹性的设定敏感，同样的份额路径可以由不同参数组合生成，机制识别要靠份额之外的数据（价格、家庭支出结构）。本课不产生内生增长：各部门的技术增速仍是外生参数，与前两课的创意生产是互补而非替代——结构模型回答「谁在增长」，创意模型回答「为什么有增长」。当代的新事实是「过早去工业化」：不少低收入国的制造业就业份额峰值低于历史对照国的同期水平，服务业接棒的路径是否还能复制老牌经济体的生产率赶超，证据与机制都还在积累，本课的框架给出读法，不给出结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构转型的两个引擎：恩格尔定律的收入效应与 Baumol 成本病的价格效应。</li><li>广义平衡增长路径同时容纳卡尔多事实与库兹涅茨事实；部门加总对替代弹性敏感。</li><li>结构红利是发展核算残差的真实成分，既不是技术也不是错配。</li><li>名义份额被相对价格污染，读结构要用实际口径。</li><li>农业生产率决定起飞前夜：食品约束不解除，剩余劳动出不了农业。</li><li>出处：Kongsamut, Rebelo and Xie, <em>REStud</em> 2001；Ngai and Pissarides, <em>REStud</em> 2007；Baumol, <em>AER</em> 1967；Gollin, Parente and Rogerson 2002；Lewis 1954。</li></ul>',6))])}const _=i(m,[["render",u]]);export{F as __pageData,_ as default};
